  const lang = () => {
    const control=document.querySelector('.language-picker select');
    if (['ko','en','tl'].includes(control?.value)) return control.value;
    try { const value=localStorage.getItem('packmate.language.v1'); if(['ko','en','tl'].includes(value)) return value; } catch (_) {}
    return ['ko','en','tl'].includes(i18n.language)?i18n.language:'ko';
  };
  const msg = key => { const a=entries[key]; return a ? a[{ko:0,en:1,tl:2}[lang()]] || a[0] : (typeof i18n.t==='function' ? i18n.t(key,lang()) : key); };
  const fmt = (key,values={}) => Object.entries(values).reduce((text,[name,value])=>text.replaceAll(`{${name}}`,String(value)),msg(key));
  const baseT=typeof i18n.t==='function'?i18n.t.bind(i18n):key=>key;
  i18n.t=(key,language=lang())=>entries[key]?(entries[key][{ko:0,en:1,tl:2}[language]??0]||entries[key][0]):baseT(key,language);
  const activityKeys=new Map(Object.keys(entries).filter(key=>key.startsWith('activity.')).map(key=>[key.slice(9),key]));
  const supplyKeys=new Map(Object.keys(entries).filter(key=>key.startsWith('supply.')).map(key=>[key.slice(7),key]));
  const subKeys=new Map(Object.keys(entries).filter(key=>key.startsWith('sub.')).map(key=>[key.slice(4),key]));
  const weatherKeys={normal:'weather.normal',hot:'weather.hot',cold:'weather.cold',rain:'weather.rain',wind:'weather.wind'};
  const purposeKeys={travel:'purpose.travel',business:'purpose.business',education:'purpose.education',personal:'purpose.personal'};
  const transportKeys={'자가용':'transport.car','기차':'transport.train','버스':'transport.bus','항공':'transport.air','기타':'transport.other'};
  const taskKeys={'할 일':'task.generic','해당 국가의 공식 입국 요건 확인':'task.entry','숙소 예약·체크인 정보 확인':'task.lodging','이동수단과 출발 시간 확인':'task.transport','일정 및 목적지 정보 확인':'task.itinerary','업무 일정 확인':'task.businessSchedule','방문 담당자 연락처 확인':'task.contact','등록 또는 신청 내역 확인':'task.registration','면접 장소 및 시간 확인':'task.interview'};
