  const builtInActivityItems={수영:['수영복','수경','수모','방수팩','슬리퍼','수건'],캠핑:['텐트','침낭','랜턴','캠핑 의자','매트','캠핑 조리도구'],등산:['등산화','등산 가방','물병','등산 스틱'],야외활동:['모자','선크림','물병'],낚시:['낚싯대','릴','미끼','구명조끼'],'사진 촬영':['카메라','여분 배터리','메모리카드','삼각대'],자전거:['헬멧','장갑','물병','수리 도구'],축구:['축구화','운동복','축구 양말','물병']};
  const activityName=name=>activityKeys.has(name)?msg(activityKeys.get(name)):name;
