  function text(el,value){if(!el)return;const nodes=[...el.childNodes].filter(node=>node.nodeType===Node.TEXT_NODE);if(nodes.length){nodes[0].nodeValue=nodes[0].nodeValue.replace(nodes[0].nodeValue.trim(),value);nodes.slice(1).forEach(node=>node.nodeValue='');}else if(!el.children.length)el.textContent=value;}
  function keyed(el,key){if(!el)return;el.setAttribute('data-i18n',key);text(el,msg(key));}
  function attr(el,name,key){if(el){el.setAttribute(`data-i18n-${name}`,key);el.setAttribute(name,msg(key));}}
  function setText(el,value){if(!el||el.textContent===value)return;const nodes=[...el.childNodes].filter(node=>node.nodeType===Node.TEXT_NODE);if(nodes.length){nodes[0].nodeValue=value;nodes.slice(1).forEach(node=>node.nodeValue='');}else if(!el.children.length)el.append(document.createTextNode(value));}
  function readTrips(){const value=window.PACKMATE_APP_DATA?.getTrips?.();return Array.isArray(value)?value:[];}
  function currentTrip(){const id=history.state?.packmateRoute?.tripId;return id?window.PACKMATE_APP_DATA?.getTrip?.(id)||null:null;}
  function purposeName(value){return purposeKeys[value]?msg(purposeKeys[value]):value||msg('purpose.travel');}
  function subPurposeName(value){return subKeys.has(value)?msg(subKeys.get(value)):value||'';}
  function transportName(value){return transportKeys[value]?msg(transportKeys[value]):value||'';}
  function durationText(value){const nights=Number(value)||0;return nights?fmt('trip.duration.nights',{nights,days:nights+1}):msg('trip.duration.sameDay');}
  function builtInItem(item){if(!item||item.custom||['direct','essential','missed'].includes(item.source)||!supplyKeys.has(item.name))return false;if(item.source!=='activity')return true;const reasons=[...(Array.isArray(item.recommendationReasons)?item.recommendationReasons:[])];const match=/추천 이유:\s*([^·]+)/.exec(String(item.detail||''));if(match)reasons.push(...match[1].split(/[,，]/));return reasons.some(reason=>{const name=String(reason).replace(/\s+활동$/,'').trim();return builtInActivityItems[name]?.includes(item.name);});}
  function itemName(item){return builtInItem(item)?msg(supplyKeys.get(item.name)):String(item?.name||'');}
  function taskName(task){return taskKeys[task?.name]?msg(taskKeys[task.name]):String(task?.name||'');}
  function translateHome(){document.querySelectorAll('#savedTrips .saved-trip-card').forEach(card=>{const id=card.querySelector('[data-open-trip]')?.dataset.openTrip,trip=readTrips().find(value=>String(value?.id)===String(id));if(!trip)return;const type=trip.type==='international'?msg('trip.international'):msg('trip.domestic');text(card.querySelector('.saved-trip-type'),`${purposeName(trip.purposeCategory)} · ${type}`);const destination=[trip.destinationCountry||trip.destination,trip.destinationCity].filter(Boolean).join(' · '),sub=subPurposeName(trip.subPurpose||trip.purpose||'관광');setText(card.querySelector('.saved-trip-destination'),[destination,sub,durationText(trip.duration)].filter(Boolean).join(' · '));const packing=Array.isArray(trip.packing)?trip.packing:[],tasks=Array.isArray(trip.tasks)?trip.tasks:[];setText(card.querySelector('.saved-trip-footer > span:first-child'),fmt('trip.card.summary',{packingDone:packing.filter(item=>item.done).length,packingTotal:packing.length,taskDone:tasks.filter(item=>item.done).length,taskTotal:tasks.length}));const remove=card.querySelector('[data-delete-trip]');if(remove){remove.setAttribute('aria-label',msg('trip.delete'));remove.title=msg('trip.delete');}});}
